changeSet.createProcedure:
CREATE OR REPLACE TRIGGER TRG_CUSTOMER_AUDIT
AFTER INSERT OR UPDATE OR DELETE ON TGT_CUSTOMER
FOR EACH ROW
DECLARE
    v_action VARCHAR2(10);
BEGIN
    IF INSERTING THEN
        v_action := 'INSERT';
    ELSIF UPDATING THEN
        v_action := 'UPDATE';
    ELSE
        v_action := 'DELETE';
    END IF;

    INSERT INTO TGT_CUSTOMER_AUDIT (
        CUSTOMER_ID, ACTION, CHANGED_BY, CHANGE_DATE,
        OLD_NAME, NEW_NAME, OLD_EMAIL, NEW_EMAIL
    ) VALUES (
        NVL(:NEW.CUSTOMER_ID, :OLD.CUSTOMER_ID),
        v_action,
        USER,
        SYSTIMESTAMP,
        :OLD.CUSTOMER_NAME,
        :NEW.CUSTOMER_NAME,
        :OLD.CUSTOMER_EMAIL,
        :NEW.CUSTOMER_EMAIL
    );
END TRG_CUSTOMER_AUDIT;
/
